mapper.sql:
FROM WF_SKIP_TASK_CONFIG RES


        AND RES.PROCESS_DEF_KEY like  #{processDefKey} || '%'


        AND RES.IS_OPEN = #{isOpen}



        AND RES.is_global = #{isGlobal}



        AND RES.tenant_id = #{tenantId}


 ORDER BY RES.CREATE_TIME DESC

mapper.update:
update WF_SKIP_TASK_CONFIG set
  IS_OPEN = #{isOpen,jdbcType=VARCHAR}
  where id in


        ${id}
